#[path="../src/app_access.rs"]mod app_access;
#[path="../src/permissions.rs"]mod permissions;
use app_access::*;
#[test]fn persistence_reset_and_invalid_profiles(){let mut t=Table::new();t.set(b"note",Some(Restriction::ReadOnly)).unwrap();assert_eq!(t.get(b"NOTE"),Some(Restriction::ReadOnly));let mut b=[0;MAX_BYTES];let n=t.encode(&mut b);let mut t=Table::parse(&b[..n]).unwrap();t.set(b"NOTE",None).unwrap();assert_eq!(t.get(b"note"),None);for b in [b"XINYI-ACCESS 1\nAPP=T\n" as &[u8],b"XINYI-ACCESS 1\nAPP=R\napp=I\n",b"XINYI-ACCESS 1\n../APP=R\n",b"XINYI-ACCESS 1\nAPP=R"]{assert!(Table::parse(b).is_err());}assert!(Table::parse(&[0;1025]).is_err());}
#[test]fn all_intersections_only_remove_authority(){use permissions::Profile::*;for original in [Trusted,ReadOnly,Media,Isolated]{for limit in [Trusted,ReadOnly,Media,Isolated]{assert_eq!(original.restrict(limit).mask()&!original.mask(),0);}}assert_eq!(Restriction::ReadOnly.mask(),ReadOnly.mask());assert_eq!(Restriction::Media.mask(),Media.mask());assert_eq!(Restriction::Isolated.mask(),Isolated.mask());}
#[test]fn capacity_and_no_path_or_argument_records(){let mut t=Table::new();for n in 0..64{t.set(format!("APP{n}").as_bytes(),Some(Restriction::Isolated)).unwrap();}assert!(t.set(b"EXTRA",Some(Restriction::Media)).is_err());let mut b=[0;MAX_BYTES];let n=t.encode(&mut b);assert!(Table::parse(&b[..n]).is_ok());t.set(b"APP0",None).unwrap();t.set(b"EXTRA",Some(Restriction::Media)).unwrap();for id in [b"APP.BIN" as &[u8],b"APP ARG",b"1APP",b"/APP"]{assert!(t.set(id,Some(Restriction::ReadOnly)).is_err());}}
